/*
 * A069756  Frobenius number of the numerical semigroup generated by
 *          consecutive squares.
 * https://oeis.org/A069756
 *
 * Offset:    2    (a(2) is the first term)
 * Keywords:  easy, nice, nonn
 * Formula:   a(n) = (n-1)*n*(n+1)*(n+2) - 1, for n >= 2 (offset 2)
 * Range:     u8 n <= 3, u16 n <= 15, u32 n <= 255, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n < 2) return 0;          /* value undefined below the offset; safe default */
    seq_t nn = (seq_t)n;
    seq_t t = (nn - 1) * nn;      /* (n-1)*n                        */
    t = t * (nn + 1);             /* * (n+1)                         */
    t = t * (nn + 2);             /* * (n+2)                         */
    return t - 1;                 /* subtract 1 to get Frobenius number */
}
